  {
    id: "northbound",
    name: "Northbound",
    sourceUrl: "https://media.example/northbound.mp3",
    capabilities: ["SONG"],
    labels: [],
    song: { durationMs: 229_000 },
    analysis: {
      status: "failed",
      cueInSeconds: null,
      cueOutSeconds: null,
      fadeInSeconds: null,
      fadeOutSeconds: null,
      overlapSeconds: null,
      integratedLufs: null,
      truePeakDbtp: null,
      error: "decode-failed",
      attempts: 2,
      nextAttemptAt: "14:50",
    },
  },
  {
    id: "morning-opener",
    name: "Morning opener",
    sourceUrl: "https://media.example/morning-opener.mp3",
    capabilities: ["INSTANT", "BACKGROUND"],
    labels: [
      { id: "morning", name: "Morning" },
