      integratedLufs: -12.4,
      truePeakDbtp: -2.1,
    },
  },
  {
    id: "weather-bed",
    name: "Weather bed",
    sourceUrl: "https://media.example/weather-bed.mp3",
    capabilities: ["BACKGROUND"],
