    target: { value: " Front pages " },
  });
  fireEvent.click(within(dialog).getByRole("button", { name: "Save label" }));
  await toast("Label updated.");
  expect(requests("PUT")).toContainEqual([
    "/media-labels/l1",
    { name: "Headlines", description: "Front pages" },
