  fireEvent.click(screen.getByRole("button", { name: "Delete Headlines" }));
  await toast("Label in use");
  routes["DELETE /media-labels/l1"] = () => {
    throw "offline";
  };
  fireEvent.click(screen.getByRole("button", { name: "Delete Headlines" }));
  await toast("Failed to delete label.");
